CREATE TABLE "bakong_payments" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "bakong_payments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint,
	"tran_id" varchar(25) NOT NULL,
	"md5" char(32) NOT NULL,
	"qr_string" text NOT NULL,
	"name" varchar(100) NOT NULL,
	"description" varchar(100),
	"amount" numeric(14, 2) NOT NULL,
	"amount_minor" bigint NOT NULL,
	"currency" varchar(3) DEFAULT 'USD' NOT NULL,
	"status" varchar(20) DEFAULT 'PENDING' NOT NULL,
	"status_access_token_hash" char(64),
	"idempotency_key" varchar(64),
	"expires_at" timestamp with time zone NOT NULL,
	"paid_at" timestamp with time zone,
	"wallet_credited_at" timestamp with time zone,
	"provider_evidence" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "bakong_payments_tran_id_key" UNIQUE("tran_id"),
	CONSTRAINT "bakong_payments_md5_key" UNIQUE("md5"),
	CONSTRAINT "bakong_payments_amount_check" CHECK ("bakong_payments"."amount" > 0),
	CONSTRAINT "bakong_payments_amount_minor_positive" CHECK ("bakong_payments"."amount_minor" > 0),
	CONSTRAINT "bakong_payments_currency_check" CHECK ("bakong_payments"."currency" IN ('USD', 'KHR')),
	CONSTRAINT "bakong_payments_status_check" CHECK ("bakong_payments"."status" IN ('PENDING', 'PAID', 'EXPIRED', 'FAILED')),
	CONSTRAINT "bakong_payments_status_access_token_hash_check" CHECK ("bakong_payments"."status_access_token_hash" IS NULL
        OR "bakong_payments"."status_access_token_hash" ~ '^[a-f0-9]{64}$')
);
--> statement-breakpoint
CREATE OR REPLACE FUNCTION bakong_payments_fill_amount_minor()
RETURNS TRIGGER AS $$
BEGIN
	IF NEW.amount_minor IS NULL THEN
		NEW.amount_minor := CASE
			WHEN NEW.currency = 'KHR' THEN ROUND(NEW.amount)::BIGINT
			ELSE ROUND(NEW.amount * 100)::BIGINT
		END;
	END IF;

	RETURN NEW;
END;
$$ LANGUAGE plpgsql;
--> statement-breakpoint
CREATE TRIGGER bakong_payments_fill_amount_minor
	BEFORE INSERT ON bakong_payments
	FOR EACH ROW
	EXECUTE FUNCTION bakong_payments_fill_amount_minor();
--> statement-breakpoint
ALTER TABLE "bakong_payments" ADD CONSTRAINT "bakong_payments_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "idx_bakong_payments_status_expires" ON "bakong_payments" USING btree ("status","expires_at");--> statement-breakpoint
CREATE UNIQUE INDEX "idx_bakong_payments_user_idempotency" ON "bakong_payments" USING btree ("user_id","idempotency_key") WHERE "bakong_payments"."idempotency_key" IS NOT NULL;--> statement-breakpoint
CREATE INDEX "idx_bakong_payments_user_status" ON "bakong_payments" USING btree ("user_id","status");
